    "1792250084664": {"fields":{"name":"Duas técnicas para um resultado à tua medida.","slogan":"A precisão das madeixas e a suavidade do balayage.","description":"Madeixas finas iluminam junto à raiz e o balayage cria uma transição suave nos comprimentos e pontas.","includesText":"Avaliação, babylights e balayage à medida, descoloração protegida, tonalização, esfumado se necessário, selagem e penteado.","achievedText":"Luz junto à raiz com degradé suave até às pontas e profundidade visual.","forWhomText":"Para reflexos finos, transição natural e profundidade na raiz.","conditionsText":"Densidade, porosidade elevada ou técnica especial podem alterar o orçamento após avaliação. Preço por comprimento e SOFT ou FULL.","alertText":"⚠️ O cabelo quimicamente tratado requer teste de viabilidade e resistência antes da confirmação."},"variants":{"hf-42f3e751-1b33-40c7-a6ad-b557efb6087b":{"name":"Médio · SOFT","description":"Iluminação subtil em zonas selecionadas."},"v_m_1792250088687":{"name":"Médio · FULL","description":"Mais madeixas para iluminar todo o cabelo."},"hf-11b257ae-b0b6-4fcf-8eb8-614aeeade21a":{"name":"Comprido · SOFT","description":"Iluminação subtil em zonas selecionadas."},"v_l_1792250088687":{"name":"Comprido · FULL","description":"Mais madeixas para iluminar todo o cabelo."},"hf-8b29ef15-f747-44dd-8c46-b3da3f65d088":{"name":"Extra comprido · SOFT","description":"Iluminação subtil em zonas selecionadas."},"v_xl_1792250088687":{"name":"Extra comprido · FULL","description":"Mais madeixas para iluminar todo o cabelo."}}},
    "1794856922956": {"fields":{"description":"Renova a luz à volta do rosto entre sessões de Balayage, Babylights ou Hybrid.","includesText":"Retoque de madeixas no contorno do rosto, adaptado ao teu Balayage, Babylights ou Hybrid.","achievedText":"Um rosto mais iluminado e uma cor renovada e harmoniosa.","forWhomText":"Para quem tem uma destas técnicas e quer um retoque entre sessões completas, cerca de quatro a cinco meses depois.","conditionsText":"Manutenção localizada sem renovar todas as madeixas. Avaliação prévia do estado do cabelo.","alertText":"⚠️ Manutenção exclusiva para madeixas feitas anteriormente no L’Studio."},"variants":{"v_m_1794857108842":{"name":"Contour · Médio","description":"Ilumina o contorno do rosto em cabelo médio entre sessões."},"v_l_1794857108842":{"name":"Contour · Comprido","description":"Ilumina o contorno do rosto, mantendo a harmonia do cabelo comprido."},"v_xl_1794857108842":{"name":"Contour · Extra comprido","description":"Renova o contorno em cabelo extra comprido sem refazer todas as madeixas."}}},
    "s3": {"fields":{"name":"Hoje é dia de um cabelo impecável.","slogan":"Tu escolhes o plano. Nós tratamos do penteado.","description":"Escolhe um liso impecável, ondas com movimento ou um acabamento cheio de personalidade.","includesText":"Lavagem profissional e produtos à medida, com secador, escova ou prancha.","achievedText":"Cabelo limpo, com forma, movimento e acabamento de salão.","forWhomText":"Para um almoço, encontro ou um dia de cabelo cuidado sem pentear em casa.","conditionsText":"Inclui lavagem, produtos e penteado. Corte, tratamentos e cor à parte.","alertText":"⚠️ Escolhe secagem natural ou penteado para cabelo curto, médio, comprido ou extra comprido."},"variants":{"v_m_1792246653964":{"name":"Secagem ao ar","description":"Lavagem profissional e secagem ao ar sem acabamento polido."},"v_l_1792246653964":{"name":"Penteado · Curto","description":"Lavagem e penteado profissionais."},"v_xl_1792246653964":{"name":"Penteado · Médio","description":"Lavagem e penteado profissionais."},"v_1792247320587":{"name":"Penteado · Comprido","description":"Lavagem e penteado profissionais."},"v_1793641193220":{"name":"Penteado · Extra comprido","description":"Lavagem e penteado profissionais."}}},
