function normalizedCatalogText(text: string): string {
  return text.normalize('NFKD').toLowerCase()
    .replace(/\p{M}/gu, '')
    .replace(/[’'´`ʻ]/g, '')
    .replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
}

export function sameCatalogText(left: string, right: string): boolean {
  if (left.trim() === right.trim()) return true;
  const normalized = normalizedCatalogText(left);
  return normalized !== '' && normalized === normalizedCatalogText(right);
}

function resolveCopy(copy: Copy | undefined, original: string | undefined): string {
  return copy && original && sameCatalogText(original, copy[0]) ? copy[1] : '';
}

function translatedCatalogText(source: string | undefined, translated: string | undefined, original: string | undefined): string {
  return source && translated && original && sameCatalogText(source, original) ? translated : '';
}

export function catalogServiceCopy(language: string, id: string, field: keyof ServiceTranslation, original: string | undefined): string {
  const copy = language === 'it' ? italianCatalog[id]?.fields : catalogByLanguage[language]?.[id];
  return resolveCopy(copy?.[field], original)
    || resolveCopy(localizedColorCatalog[language]?.[id]?.fields[field], original)
    || translatedCatalogText(catalogSources[id]?.fields[field], localizedCatalogDetails[language]?.[id]?.fields[field], original);
}

export function catalogVariantCopy(language: string, serviceId: string, variantId: string, field: VariantField, original: string | undefined): string {
  const catalogs = language === 'it' ? italianCatalog : localizedColorCatalog[language];
  const packaged = catalogs?.[serviceId]?.variants;
  const sources = catalogSources[serviceId]?.variants;
  const translations = localizedCatalogDetails[language]?.[serviceId]?.variants;
  const variantCopy = (id: string) => resolveCopy(packaged?.[id]?.[field], original)
    || translatedCatalogText(sources?.[id]?.[field], translations?.[id]?.[field], original);
  const byId = variantCopy(variantId);
  if (byId || !original) return byId;
  // The editor can regenerate variant IDs. Only reuse an unambiguous matching translation.
  const matchingCopy = new Set(Object.keys({...packaged, ...translations}).map(variantCopy).filter(Boolean));
  return matchingCopy.size === 1 ? [...matchingCopy][0] : '';
}

